package com.abogacia.microservicio_ciudadanos.recuperacion;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import com.abogacia.microservicio_ciudadanos.correo.InterfazCorreo;
class RecuperacionActivaTest {
 @Test void solicitudTieneRespuestaGenericaYGuardaHashDeToken(){
  var jdbc=mock(JdbcTemplate.class);var passwords=mock(PasswordEncoder.class);var mail=mock(InterfazCorreo.class);when(mail.recuperacionDisponible()).thenReturn(true);
  when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("id",1L,"mail","dual@example.invalid")),List.of());
  var c=new RecuperacionController(jdbc,passwords,mail,true);assertTrue(c.solicitar(new RecuperacionController.Solicitud("dual@example.invalid")).get("mensaje").startsWith("Si la cuenta"));
  var token=org.mockito.ArgumentCaptor.forClass(String.class);verify(mail).enviarRecuperacion(eq("dual@example.invalid"),token.capture());assertTrue(token.getValue().matches("[A-Za-z0-9_-]{43}"));
  verify(jdbc).update(contains("insert into recuperacion_cuenta"),eq(1L),argThat((Object h)->h instanceof String&&((String)h).matches("[0-9a-f]{64}")&&!h.equals(token.getValue())));
 }
 @Test void tokenInvalidoOVencidoNoCambiaContrasena(){var j=mock(JdbcTemplate.class);var m=mock(InterfazCorreo.class);when(m.recuperacionDisponible()).thenReturn(true);var c=new RecuperacionController(j,mock(PasswordEncoder.class),m,true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->c.confirmar(new RecuperacionController.Confirmacion("A".repeat(43),"NuevaClaveSintetica","NuevaClaveSintetica")));verify(j,never()).update(anyString(),any(Object[].class));}
 @Test void recuperacionConsumeTokenYCambiaSoloSuTabla(){var j=mock(JdbcTemplate.class);var p=mock(PasswordEncoder.class);var m=mock(InterfazCorreo.class);when(m.recuperacionDisponible()).thenReturn(true);when(p.encode("NuevaClaveSintetica")).thenReturn("HASH-SINTETICO");when(j.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("id",1L)),List.of(Map.of("cuenta_id",1L)),List.of());when(j.update(startsWith("update ciudadano "),any(Object[].class))).thenReturn(1);var c=new RecuperacionController(j,p,m,true);var r=new RecuperacionController.Confirmacion("A".repeat(43),"NuevaClaveSintetica","NuevaClaveSintetica");c.confirmar(r);verify(j).update(startsWith("update ciudadano "),eq("HASH-SINTETICO"),eq(1L));verify(j).update("delete from recuperacion_cuenta where cuenta_id=?",1L);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->c.confirmar(r));}
}
